'use strict';

/**
 * Устанавливает поле record.requestId одним из способов:
 *  – из req.id
 *  - из req.requestId
 *  – из заголовка req.headers['x-request-id']
 *  – из заголовка req.headers['x-req-id']
 *
 * @returns {Function}
 */
module.exports = () => {
    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        let req = record.req;
        if (!req || record.requestId) {
            return;
        }

        record.requestId = req.id ||
            req.requestId ||
            (req.headers && (req.headers['x-request-id'] || req.headers['x-req-id'])) ||
            undefined;
    };
};
